INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5040009, 736093, 89723, '<td valign="top">This is fantastic. The lighting is perfect. I really hope this does well for you.</td>', 'This is fantastic. The lighting is perfect. I really hope this does well for you.', '2008-11-03 00:12:43.000000', NULL, 1),
(5040016, 735728, 42601, '<td valign="top">Man, pity the puppy in the foreground seems a little out of focus, but great shot nonetheless - 9</td>', 'Man, pity the puppy in the foreground seems a little out of focus, but great shot nonetheless - 9', '2008-11-03 00:14:03.000000', NULL, 1),
(5040022, 735840, 42601, '<td valign="top">I like how the grass kinda resembles waves in the water, nice shot.</td>', 'I like how the grass kinda resembles waves in the water, nice shot.', '2008-11-03 00:14:49.000000', NULL, 1),
(5040033, 735752, 42601, '<td valign="top">Brilliant. 10</td>', 'Brilliant. 10', '2008-11-03 00:18:10.000000', NULL, 1),
(5040046, 735156, 42601, '<td valign="top">Very nice.</td>', 'Very nice.', '2008-11-03 00:20:12.000000', NULL, 1),
(5040072, 736006, 68947, '<td valign="top">Great shot...love the contrast between the glitzy ball and the subject of your shot.  Somehow though, this portrays more "poverty" to me than abandonded.  Still, great shot!</td>', 'Great shot...love the contrast between the glitzy ball and the subject of your shot.  Somehow though, this portrays more "poverty" to me than abandonded.  Still, great shot!', '2008-11-03 00:25:44.000000', NULL, 1),
(5040080, 735759, 68947, '<td valign="top">If it weren''t for the title, I''d not have gotten the idea of "abandoned" being part of this shot.  It seems more like a high altitude landscape.</td>', 'If it weren''t for the title, I''d not have gotten the idea of "abandoned" being part of this shot.  It seems more like a high altitude landscape.', '2008-11-03 00:28:46.000000', NULL, 1),
(5040097, 736081, 68947, '<td valign="top">Lovely contrast against the background, DOF is great.  Says "abandonded" to me.</td>', 'Lovely contrast against the background, DOF is great.  Says "abandonded" to me.', '2008-11-03 00:33:04.000000', NULL, 1),
(5040125, 736083, 94265, '<td valign="top">I think we have a ribboner here. Very funny, nice colours and great scenery.</td>', 'I think we have a ribboner here. Very funny, nice colours and great scenery.', '2008-11-03 00:42:55.000000', NULL, 1),
(5040135, 735939, 94265, '<td valign="top">I believe this could be a ribboner. Awesome shot, great processing.</td>', 'I believe this could be a ribboner. Awesome shot, great processing.', '2008-11-03 00:56:01.000000', NULL, 1),
(5040271, 736091, 37252, '<td valign="top">I feel your title is pretty close to how I perceive this, as I do find this to be over processed, but not a disaster. I just feel the pp took away some interesting details.</td>', 'I feel your title is pretty close to how I perceive this, as I do find this to be over processed, but not a disaster. I just feel the pp took away some interesting details.', '2008-11-03 03:00:45.000000', NULL, 1),
(5040360, 735857, 70393, '<td valign="top">n</td>', 'n', '2008-11-03 04:48:58.000000', NULL, 1),
(5040373, 734489, 36606, '<td valign="top">should have gone for the colour mate. good luck!</td>', 'should have gone for the colour mate. good luck!', '2008-11-03 05:15:38.000000', NULL, 1),
(5040540, 734924, 80904, '<td valign="top">I think I recognize that silhouette</td>', 'I think I recognize that silhouette', '2008-11-03 08:44:34.000000', NULL, 1),
(5040562, 735825, 92611, '<td valign="top">I like the idea and the compostion.  The only thing I really have trouble with is the static on the screen.  I think a cracked screen or just even a black screen would have improved the capture.  That is only my opinion though.  Great idea and nice shot overall.</td>', 'I like the idea and the compostion.  The only thing I really have trouble with is the static on the screen.  I think a cracked screen or just even a black screen would have improved the capture.  That is only my opinion though.  Great idea and nice shot overall.', '2008-11-03 08:53:02.000000', NULL, 1),
(5040563, 736021, 92611, '<td valign="top">Funny and entertaining!  The treatment really accentuates the "abandoned" theme.</td>', 'Funny and entertaining!  The treatment really accentuates the "abandoned" theme.', '2008-11-03 08:53:53.000000', NULL, 1),
(5040571, 736131, 92611, '<td valign="top">Absolutely beautiful!!  Great shot!</td>', 'Absolutely beautiful!!  Great shot!', '2008-11-03 08:56:43.000000', NULL, 1),
(5040641, 735698, 98141, '<td valign="top">Very clever, though I''m not sure if everybody will be familiar with the Dickens character. From what I remember, this is the time that she was abandoned at the alter? Perhaps too much foreknowledge is needed to "get" this, but I hope not. I like the blur and the ghostly feel of Miss Havisham inthe back. I find the white gap in the lower left corner a little distracting, a version with the clock filling that corner would be cool.</td>', 'Very clever, though I''m not sure if everybody will be familiar with the Dickens character. From what I remember, this is the time that she was abandoned at the alter? Perhaps too much foreknowledge is needed to "get" this, but I hope not. I like the blur and the ghostly feel of Miss Havisham inthe back. I find the white gap in the lower left corner a little distracting, a version with the clock filling that corner would be cool.', '2008-11-03 09:29:55.000000', NULL, 1),
(5040645, 736028, 98141, '<td valign="top">I think giving this machine a wider frame with more open space would heighten the feeling of abandonment. Right now it''s hard to tell if it''s really "abandoned" because it lacks context.</td>', 'I think giving this machine a wider frame with more open space would heighten the feeling of abandonment. Right now it''s hard to tell if it''s really "abandoned" because it lacks context.', '2008-11-03 09:30:43.000000', NULL, 1),
(5040647, 735940, 98141, '<td valign="top">The black and white made it a little hard to tell what I was looking at at first, but the title made it more clear. I''d like to see a version in color.</td>', 'The black and white made it a little hard to tell what I was looking at at first, but the title made it more clear. I''d like to see a version in color.', '2008-11-03 09:31:19.000000', NULL, 1),
(5040652, 735794, 98141, '<td valign="top">I think a sharper deer would stand out more against the background. I love the yellow. I also think editing out the grass/cropping the bottom closer to the deer would improve it.<br/><br/><i>Message edited by author 2008-11-13 09:37:27.</i></td>', 'I think a sharper deer would stand out more against the background. I love the yellow. I also think editing out the grass/cropping the bottom closer to the deer would improve it.', '2008-11-03 09:32:16.000000', '2008-11-13 09:37:27.000000', 1),
(5040655, 735674, 98141, '<td valign="top">I love the torn flag detail and I think you included enough landscape for the machine to really "feel" lonely. Nice pic.</td>', 'I love the torn flag detail and I think you included enough landscape for the machine to really "feel" lonely. Nice pic.', '2008-11-03 09:32:55.000000', NULL, 1),
(5040656, 736093, 98141, '<td valign="top">Very haunted feeling, love the house being blurred like that, love the lighting and the colors.</td>', 'Very haunted feeling, love the house being blurred like that, love the lighting and the colors.', '2008-11-03 09:33:33.000000', NULL, 1),
(5040672, 735658, 98141, '<td valign="top">This just seems like a picture of nothing to me... If the object on the far left wasn''t blocked from view by the plants, I would like it better, it would feel more complete to me. Nothing really stands out as the focus/subject; it feels almost like a landscape shot but without all the grandeur. Just my first thoughts.</td>', 'This just seems like a picture of nothing to me... If the object on the far left wasn''t blocked from view by the plants, I would like it better, it would feel more complete to me. Nothing really stands out as the focus/subject; it feels almost like a landscape shot but without all the grandeur. Just my first thoughts.', '2008-11-03 09:37:16.000000', NULL, 1),
(5040677, 735659, 98141, '<td valign="top">I like the spray paint and hold in the deck details here, also the expanse of land as the background, good shot.</td>', 'I like the spray paint and hold in the deck details here, also the expanse of land as the background, good shot.', '2008-11-03 09:38:13.000000', NULL, 1),
(5040686, 735721, 3102, '<td valign="top">Whoa... this is a textbook example of overusing HDR.</td>', 'Whoa... this is a textbook example of overusing HDR.', '2008-11-03 09:40:09.000000', NULL, 1),
(5040687, 736072, 98141, '<td valign="top">I would like to see a shot of this that included the abandoned gas station, I think that would make it more effective. The plant growth takes up so much of the pic and obscures words/numbers that, I feel, are necessary in such a close crop to really get the impact of the pic.</td>', 'I would like to see a shot of this that included the abandoned gas station, I think that would make it more effective. The plant growth takes up so much of the pic and obscures words/numbers that, I feel, are necessary in such a close crop to really get the impact of the pic.', '2008-11-03 09:40:13.000000', NULL, 1),
(5040692, 735678, 98141, '<td valign="top">Very creepy mood, I like the trees through the window. I suggest a closer crop on the left to make it a little more symmetrical. Cool pic.</td>', 'Very creepy mood, I like the trees through the window. I suggest a closer crop on the left to make it a little more symmetrical. Cool pic.', '2008-11-03 09:41:12.000000', NULL, 1),
(5040709, 735746, 98141, '<td valign="top">I don''t like the darkness in the upper left corner. I do like the broken floorboard in the bottom right.</td>', 'I don''t like the darkness in the upper left corner. I do like the broken floorboard in the bottom right.', '2008-11-03 09:43:28.000000', NULL, 1),
(5040711, 735478, 98141, '<td valign="top">Seems a little out of focus to me? The lines are a little boring, straight across and straight up and down. Try adding a few diagonal lines to increase visual interest in your shots.</td>', 'Seems a little out of focus to me? The lines are a little boring, straight across and straight up and down. Try adding a few diagonal lines to increase visual interest in your shots.', '2008-11-03 09:44:18.000000', NULL, 1),
(5040716, 735558, 98141, '<td valign="top">I like your subject, seems very run-down and long-abandoned. I like the leaves. Would love to see a version in color. Like the for sale sign in the window, great detail. Good pic.</td>', 'I like your subject, seems very run-down and long-abandoned. I like the leaves. Would love to see a version in color. Like the for sale sign in the window, great detail. Good pic.', '2008-11-03 09:45:10.000000', NULL, 1),
(5040718, 735525, 98141, '<td valign="top">Too dark.</td>', 'Too dark.', '2008-11-03 09:45:36.000000', NULL, 1),
(5040720, 736131, 98141, '<td valign="top">I like this a lot, love the dark line that seperates teh horizon from the water, love the monochromatic choice, love teh shadows. Great pic.</td>', 'I like this a lot, love the dark line that seperates teh horizon from the water, love the monochromatic choice, love teh shadows. Great pic.', '2008-11-03 09:46:45.000000', NULL, 1),
(5040724, 735741, 98141, '<td valign="top">I like the subject, but I feel like it''s a little boring... All straight horizontal and vertical lines, nothing really captures a feeling of abandonment or sadness or lonliness or anything. Try to give the building a personality and an emotion and it will really pop.</td>', 'I like the subject, but I feel like it''s a little boring... All straight horizontal and vertical lines, nothing really captures a feeling of abandonment or sadness or lonliness or anything. Try to give the building a personality and an emotion and it will really pop.', '2008-11-03 09:48:07.000000', NULL, 1),
(5040726, 735552, 98141, '<td valign="top">Haha, I feel like Big Bug is giving Little But the finger with his hind leg! Very funny, but I''m not sure it captures the feeling of "abandoned." Do like the colors though.</td>', 'Haha, I feel like Big Bug is giving Little But the finger with his hind leg! Very funny, but I''m not sure it captures the feeling of "abandoned." Do like the colors though.', '2008-11-03 09:49:36.000000', NULL, 1),
(5040728, 735836, 98141, '<td valign="top">I love the colors in this and the visual lines the tracks make. Very cool.</td>', 'I love the colors in this and the visual lines the tracks make. Very cool.', '2008-11-03 09:49:59.000000', NULL, 1),
(5040733, 735699, 98141, '<td valign="top">Ah, soon we''re going to get snow here and this shot is exactly what I''m afraid of finding in my driveway every morning... ugh.</td>', 'Ah, soon we''re going to get snow here and this shot is exactly what I''m afraid of finding in my driveway every morning... ugh.', '2008-11-03 09:50:55.000000', NULL, 1),
(5040742, 735983, 98141, '<td valign="top">Love the color choice, love that the bike is missing front wheel and the peeling paint. Great pic.</td>', 'Love the color choice, love that the bike is missing front wheel and the peeling paint. Great pic.', '2008-11-03 09:52:51.000000', NULL, 1),
(5040747, 736128, 98141, '<td valign="top">I like this in b&amp;w, I like the child in the background and the focus on the doll is pretty sharp. Nice pic.</td>', 'I like this in b&w, I like the child in the background and the focus on the doll is pretty sharp. Nice pic.', '2008-11-03 09:53:49.000000', NULL, 1),
(5040752, 735951, 98141, '<td valign="top">Definitely fits the challenge, but it is a little boring, doesn''t really stand out among the other pics... No mood, no personality.</td>', 'Definitely fits the challenge, but it is a little boring, doesn''t really stand out among the other pics... No mood, no personality.', '2008-11-03 09:54:48.000000', NULL, 1),
(5040757, 735824, 98141, '<td valign="top">Very nice editing with the colors, Buckshot really stands out from the rest of the pic! Love how dirty it looks.</td>', 'Very nice editing with the colors, Buckshot really stands out from the rest of the pic! Love how dirty it looks.', '2008-11-03 09:55:38.000000', NULL, 1),
(5040760, 735752, 98141, '<td valign="top">Love the colors in this! The snow, the sunset, the rusty machine, all the elements really work together here, great pic!</td>', 'Love the colors in this! The snow, the sunset, the rusty machine, all the elements really work together here, great pic!', '2008-11-03 09:56:36.000000', NULL, 1),
(5040762, 735746, 68947, '<td valign="top">LOL...do I WANT to know what''s smeared on the front porch? *wink*  I like the tunnel like effect to this shot.  Simple and yet portrays the abandoned very well.</td>', 'LOL...do I WANT to know what''s smeared on the front porch? *wink*  I like the tunnel like effect to this shot.  Simple and yet portrays the abandoned very well.', '2008-11-03 09:57:12.000000', NULL, 1),
(5040764, 735271, 98141, '<td valign="top">Aw, poor baby! I think the darkness around the edges, whether done with the natural lighting or added during editing, work well in this pic (I''m not usually a fan).</td>', 'Aw, poor baby! I think the darkness around the edges, whether done with the natural lighting or added during editing, work well in this pic (I''m not usually a fan).', '2008-11-03 09:57:36.000000', NULL, 1),
(5040767, 735948, 98141, '<td valign="top">I like the shack behind her, I like that you made her colors stand out from the b&amp;w. I''m not sure about the story behind the pic: was she dropped off to fend for herself in the backwoods, did her car break down, run out of gas? Another element in the picture (car driving away, broken, etc.) would add more depth to the story of the character in the pic imho.</td>', 'I like the shack behind her, I like that you made her colors stand out from the b&w. I''m not sure about the story behind the pic: was she dropped off to fend for herself in the backwoods, did her car break down, run out of gas? Another element in the picture (car driving away, broken, etc.) would add more depth to the story of the character in the pic imho.', '2008-11-03 09:59:28.000000', NULL, 1),
(5040770, 736012, 98141, '<td valign="top">I love the blank sky and the way the house seems huge against that blank canvas. B&amp;W works great here. I suggest cloning out the wisp of hair coming from under the hood, it is distracting.</td>', 'I love the blank sky and the way the house seems huge against that blank canvas. B&W works great here. I suggest cloning out the wisp of hair coming from under the hood, it is distracting.', '2008-11-03 10:00:24.000000', NULL, 1),
(5040771, 736091, 98141, '<td valign="top">This seems like a comic book pic to me, but it certainly has an air of abandonment.</td>', 'This seems like a comic book pic to me, but it certainly has an air of abandonment.', '2008-11-03 10:01:28.000000', NULL, 1),
(5040773, 735637, 98141, '<td valign="top">I like the lighting here, the way the sun seems to be travelling up the tracks. Can''t believe you got a shot with no people. The pole that''s almost in the middle of the pic is a pain, would like it better if it were more to the side.</td>', 'I like the lighting here, the way the sun seems to be travelling up the tracks. Can''t believe you got a shot with no people. The pole that''s almost in the middle of the pic is a pain, would like it better if it were more to the side.', '2008-11-03 10:02:37.000000', NULL, 1),
(5040774, 734924, 86447, '<td valign="top">It looks like she''s searching for her arms.  LOL<br/> <br/>I wish there were one of them showing.  I like the light and the mood.</td>', 'It looks like she''s searching for her arms.  LOL I wish there were one of them showing.  I like the light and the mood.', '2008-11-03 10:02:56.000000', NULL, 1),
(5040776, 735897, 86447, '<td valign="top">My fave from the challenge.  I hope this does well for you.</td>', 'My fave from the challenge.  I hope this does well for you.', '2008-11-03 10:03:23.000000', NULL, 1),
(5040779, 735662, 98141, '<td valign="top">Seems like it''s open and decorated, doesn''t feel abandoned at all? Don''t like the composition or the crop. Do like the colors.</td>', 'Seems like it''s open and decorated, doesn''t feel abandoned at all? Don''t like the composition or the crop. Do like the colors.', '2008-11-03 10:03:32.000000', NULL, 1),
(5040783, 735760, 98141, '<td valign="top">Good, fits challenge, interesting subject, but I think maybe the crop is a tad too close? Something about this feel unimpressive. Just a pic of an old car. No mood, no emotion. Good pic, but lacks conviction.</td>', 'Good, fits challenge, interesting subject, but I think maybe the crop is a tad too close? Something about this feel unimpressive. Just a pic of an old car. No mood, no emotion. Good pic, but lacks conviction.', '2008-11-03 10:05:12.000000', NULL, 1),
(5040786, 735791, 98141, '<td valign="top">Great colors, lover her umbrella and the rain blocking the rest of the street from our vision. Great pic.</td>', 'Great colors, lover her umbrella and the rain blocking the rest of the street from our vision. Great pic.', '2008-11-03 10:05:44.000000', NULL, 1),
(5040787, 735825, 68947, '<td valign="top">Has a deeper meaning and well portrayed.  Everything but the tv and a few blades of grass and pebbles in the foreground is in focus.  I''m sure that the scoring will be good on this one.  It will all depend upon the "literalists" and whether they can allow/permit the deeper thinking.  Sometimes, I think that if it''s not a pretty stock shot, no amount of meaning will make it do well. SIGH</td>', 'Has a deeper meaning and well portrayed.  Everything but the tv and a few blades of grass and pebbles in the foreground is in focus.  I''m sure that the scoring will be good on this one.  It will all depend upon the "literalists" and whether they can allow/permit the deeper thinking.  Sometimes, I think that if it''s not a pretty stock shot, no amount of meaning will make it do well. SIGH', '2008-11-03 10:05:56.000000', NULL, 1),
(5040790, 735840, 98141, '<td valign="top">Hm, I think that I would like this better if it included more of the subject... Without the title I would have no idea what this object was and it certainly wouldn''t have represented abandonment to me.</td>', 'Hm, I think that I would like this better if it included more of the subject... Without the title I would have no idea what this object was and it certainly wouldn''t have represented abandonment to me.', '2008-11-03 10:06:57.000000', NULL, 1),
(5040793, 735914, 68947, '<td valign="top">This really portrays abandoned including the bared trees!  However, I think it may take a creaming because of the lack of focus and detail in the main subject.  I could be wrong and hope that I am!</td>', 'This really portrays abandoned including the bared trees!  However, I think it may take a creaming because of the lack of focus and detail in the main subject.  I could be wrong and hope that I am!', '2008-11-03 10:08:12.000000', NULL, 1),
(5040798, 735828, 98141, '<td valign="top">I like the state of the door, I like the white background behind the person, I like the way the doorway divides the man from the door. I would liek to see outtakes from this shot, maybe one with a little more area covered? I mean to say, the whole man and the whole door? Who is abandoned, the home or the man?</td>', 'I like the state of the door, I like the white background behind the person, I like the way the doorway divides the man from the door. I would liek to see outtakes from this shot, maybe one with a little more area covered? I mean to say, the whole man and the whole door? Who is abandoned, the home or the man?', '2008-11-03 10:09:11.000000', NULL, 1),
(5040800, 736013, 98141, '<td valign="top">Very dreamlike. Lovely.</td>', 'Very dreamlike. Lovely.', '2008-11-03 10:09:41.000000', NULL, 1),
(5040803, 736126, 98141, '<td valign="top">Cool shot, different take on the challenge, I like it. I would prefer for the windows to all be equidistant from the edges; that is, there are no windows on the top edge but there are half windows on the bottom? I think that more symmetrical framing would enhance the pic.</td>', 'Cool shot, different take on the challenge, I like it. I would prefer for the windows to all be equidistant from the edges; that is, there are no windows on the top edge but there are half windows on the bottom? I think that more symmetrical framing would enhance the pic.', '2008-11-03 10:11:03.000000', NULL, 1),
(5040807, 736009, 98141, '<td valign="top">Very dreamlike, sometimes I feel like I''m looking at the bottom of a wishing well, sometimes through a window, now to the bottom of a shallow, clear pond. And I''m not sure how, since there''s not really a definite "abandoned" subject, but I think you captured the mood brilliantly.</td>', 'Very dreamlike, sometimes I feel like I''m looking at the bottom of a wishing well, sometimes through a window, now to the bottom of a shallow, clear pond. And I''m not sure how, since there''s not really a definite "abandoned" subject, but I think you captured the mood brilliantly.', '2008-11-03 10:12:37.000000', NULL, 1),
(5040809, 735809, 98141, '<td valign="top">Cool pic, likethe colors, like the comoposition.</td>', 'Cool pic, likethe colors, like the comoposition.', '2008-11-03 10:12:55.000000', NULL, 1),
(5040812, 736084, 98141, '<td valign="top">I saw a toilet on the side of the road yesterday! I considered stopping for a pic, but decided not to. Strange how much more common this is than I would have expected! That said, the lighting seems dull here, focus seems off, and nothing really pops. Certainly fits the challenge, but the technicals could use more attention.</td>', 'I saw a toilet on the side of the road yesterday! I considered stopping for a pic, but decided not to. Strange how much more common this is than I would have expected! That said, the lighting seems dull here, focus seems off, and nothing really pops. Certainly fits the challenge, but the technicals could use more attention.', '2008-11-03 10:14:11.000000', NULL, 1),
(5040815, 735684, 98141, '<td valign="top">I like the colors (or lack thereof) and the pattern of the bricks below her. Good setting. I''d like to see a version with her whole body included, I feel that a good facial expression could enhance the idea of being abandoned in this pic.</td>', 'I like the colors (or lack thereof) and the pattern of the bricks below her. Good setting. I''d like to see a version with her whole body included, I feel that a good facial expression could enhance the idea of being abandoned in this pic.', '2008-11-03 10:15:47.000000', NULL, 1),
(5040816, 735947, 98141, '<td valign="top">Beautiful. Great mood. I''ve seen a lot of "abandoned barn/house/cottage/building" shots in this challenge, and this one is the first to really capture a mood. Well done.</td>', 'Beautiful. Great mood. I''ve seen a lot of "abandoned barn/house/cottage/building" shots in this challenge, and this one is the first to really capture a mood. Well done.', '2008-11-03 10:16:31.000000', NULL, 1),
(5040817, 736108, 98141, '<td valign="top">Seems a little flat. I would like it better if there was more of a distinction between the foreground/subject and the background.</td>', 'Seems a little flat. I would like it better if there was more of a distinction between the foreground/subject and the background.', '2008-11-03 10:17:13.000000', NULL, 1),
(5040819, 735744, 98141, '<td valign="top">Great colors! This pops. Love the cow in the front.</td>', 'Great colors! This pops. Love the cow in the front.', '2008-11-03 10:17:40.000000', NULL, 1),
(5040822, 735965, 98141, '<td valign="top">I like the gulls lined up above and the rusty state of teh Cofran Cadiz. I''d like to see a slightly wider crop? I think that including a little more background can enhance a feeling of abandonment.</td>', 'I like the gulls lined up above and the rusty state of teh Cofran Cadiz. I''d like to see a slightly wider crop? I think that including a little more background can enhance a feeling of abandonment.', '2008-11-03 10:18:48.000000', NULL, 1),
(5040823, 735553, 98141, '<td valign="top">I swear I had a dress just like that when I was growing up, and I loved it. I like the way she''s peeking around the corner a bit. Without the title, though, it wouldn''t have really represented abandonment to me. I don''t think the pic reflects the mood of abandonment in a straightforward manner.</td>', 'I swear I had a dress just like that when I was growing up, and I loved it. I like the way she''s peeking around the corner a bit. Without the title, though, it wouldn''t have really represented abandonment to me. I don''t think the pic reflects the mood of abandonment in a straightforward manner.', '2008-11-03 10:20:13.000000', NULL, 1),
(5040826, 735927, 98141, '<td valign="top">I like the pic, but I''m not sure I like the post-processing. Would love to see what it looks like in color.</td>', 'I like the pic, but I''m not sure I like the post-processing. Would love to see what it looks like in color.', '2008-11-03 10:20:56.000000', NULL, 1),
