(5041037, 735659, 63398, '<td valign="top">Great poignant message. Great angle &amp; perspective. Provocative....7</td>', 'Great poignant message. Great angle & perspective. Provocative....7', '2008-11-03 11:54:32.000000', NULL, 1),
(5041039, 735853, 63398, '<td valign="top">Wonderfully creative and executed. I like the faint reflection of the strip on the surface. Subtle &amp; classy. 8</td>', 'Wonderfully creative and executed. I like the faint reflection of the strip on the surface. Subtle & classy. 8', '2008-11-03 11:55:21.000000', NULL, 1),
