(5041047, 735841, 63398, '<td valign="top">Good image though I would have liked to see more of the vehicle to carry the theme. 6</td>', 'Good image though I would have liked to see more of the vehicle to carry the theme. 6', '2008-11-03 11:57:46.000000', NULL, 1),
(5041049, 735712, 63398, '<td valign="top">Very interesting light hue. Very soft and warm. Nicely done. 7</td>', 'Very interesting light hue. Very soft and warm. Nicely done. 7', '2008-11-03 11:58:25.000000', NULL, 1),
(5041050, 735992, 63398, '<td valign="top">Good find. Nicely shown. Love the urban art. 6</td>', 'Good find. Nicely shown. Love the urban art. 6', '2008-11-03 11:58:57.000000', NULL, 1),
(5041051, 735757, 63398, '<td valign="top">Great discovery! What a great scene! 7</td>', 'Great discovery! What a great scene! 7', '2008-11-03 11:59:28.000000', NULL, 1),
