INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5041319, 736015, 98141, '<td valign="top">I''m not really sure what the blue object is? It is, however, abandoned and I think the sky looks fantastic. The corners are a little dark and I think it takes away from the pic.</td>', 'I''m not really sure what the blue object is? It is, however, abandoned and I think the sky looks fantastic. The corners are a little dark and I think it takes away from the pic.', '2008-11-03 14:09:10.000000', NULL, 1),
(5041321, 736085, 98141, '<td valign="top">Cool perspective, and this looks very abandoned! I like the crop, too.</td>', 'Cool perspective, and this looks very abandoned! I like the crop, too.', '2008-11-03 14:09:48.000000', NULL, 1),
(5041324, 736123, 98141, '<td valign="top">I like this, it has depth, it has wow factor (wow! that''s big) and nice composition.</td>', 'I like this, it has depth, it has wow factor (wow! that''s big) and nice composition.', '2008-11-03 14:10:26.000000', NULL, 1),
(5041327, 735745, 98141, '<td valign="top">Too plain, no wow factor. Fine pic though, and fits the challenge.</td>', 'Too plain, no wow factor. Fine pic though, and fits the challenge.', '2008-11-03 14:11:02.000000', NULL, 1),
(5041331, 735967, 98141, '<td valign="top">Nice dof, I like the b&amp;w, great positioning of the subject in the frame. Love it!</td>', 'Nice dof, I like the b&w, great positioning of the subject in the frame. Love it!', '2008-11-03 14:11:31.000000', NULL, 1),
(5041335, 735836, 70265, '<td valign="top">wonderful clarity, color and POV</td>', 'wonderful clarity, color and POV', '2008-11-03 14:12:14.000000', NULL, 1),
(5041336, 736007, 98141, '<td valign="top">From this challenge, it seems like there are a lot of neglected trains out there. I like this shot, the colors, the gloomy sky.</td>', 'From this challenge, it seems like there are a lot of neglected trains out there. I like this shot, the colors, the gloomy sky.', '2008-11-03 14:12:19.000000', NULL, 1),
(5041339, 735834, 98141, '<td valign="top">The first thing I notice here is the pole going right down the center of the picture... it''s very distracting and takes away from your subjects - though you did a nice job of focusing on them.</td>', 'The first thing I notice here is the pole going right down the center of the picture... it''s very distracting and takes away from your subjects - though you did a nice job of focusing on them.', '2008-11-03 14:13:16.000000', NULL, 1),
(5041345, 735864, 98141, '<td valign="top">Very blue, the room feels very cold and very creepy, nice creation of ambience.</td>', 'Very blue, the room feels very cold and very creepy, nice creation of ambience.', '2008-11-03 14:14:14.000000', NULL, 1),
(5041346, 736081, 98141, '<td valign="top">Felt I was looking at a heart at first glance. Nice dof. Cool pic. Great colors. I like it a lot.</td>', 'Felt I was looking at a heart at first glance. Nice dof. Cool pic. Great colors. I like it a lot.', '2008-11-03 14:14:49.000000', NULL, 1),
(5041347, 735684, 70265, '<td valign="top">I really love her stance and the way you''ve captured anonymity by chopping off the head ... The graffiti on the wall behind is in just the right place to add a touch of humour. Yes, this is excellent, even though I have to say it doesn''t scream ''abandoned'' to me, without the title tie in anyway. Highly rated.</td>', 'I really love her stance and the way you''ve captured anonymity by chopping off the head ... The graffiti on the wall behind is in just the right place to add a touch of humour. Yes, this is excellent, even though I have to say it doesn''t scream ''abandoned'' to me, without the title tie in anyway. Highly rated.', '2008-11-03 14:15:01.000000', NULL, 1),
(5041350, 736012, 70265, '<td valign="top">Coley? You rock!</td>', 'Coley? You rock!', '2008-11-03 14:15:28.000000', NULL, 1),
(5041352, 735703, 70265, '<td valign="top">I really enjoy the tones in this.</td>', 'I really enjoy the tones in this.', '2008-11-03 14:15:49.000000', NULL, 1),
(5041356, 735757, 98141, '<td valign="top">Fits the challenge, but it has a very "snapshot"ish quality. Maybe that''s what you were going for, but I feel that photos that look less like snapshots tend to do better with the voters. No wow factor here - except maybe: "Wow! those monitors are humongoid."</td>', 'Fits the challenge, but it has a very "snapshot"ish quality. Maybe that''s what you were going for, but I feel that photos that look less like snapshots tend to do better with the voters. No wow factor here - except maybe: "Wow! those monitors are humongoid."', '2008-11-03 14:16:42.000000', NULL, 1),
(5041359, 735711, 70265, '<td valign="top">This is an unique idea and I love the way you''ve captured it --- the tones used in PP, the vertical composition, the dark vignetted edges. Yes, this works ...</td>', 'This is an unique idea and I love the way you''ve captured it --- the tones used in PP, the vertical composition, the dark vignetted edges. Yes, this works ...', '2008-11-03 14:17:14.000000', NULL, 1),
(5041361, 736098, 98141, '<td valign="top">I''ve seen a lot of pics of tractors/cars/vehicles/machines alone in a field in this challenge, but I think you figured out how to do it right. Great use of dof, great framing, has emotion, and I like it a lot.</td>', 'I''ve seen a lot of pics of tractors/cars/vehicles/machines alone in a field in this challenge, but I think you figured out how to do it right. Great use of dof, great framing, has emotion, and I like it a lot.', '2008-11-03 14:17:35.000000', NULL, 1),
(5041365, 736007, 70265, '<td valign="top">Great leading lines. Also the muted tones work well for this subject. Nice work.</td>', 'Great leading lines. Also the muted tones work well for this subject. Nice work.', '2008-11-03 14:18:30.000000', NULL, 1),
(5041367, 735982, 98141, '<td valign="top">I think I would like this better if it had been taken with the camera held lower. Perhaps a low angle shot to give the doorway/building a sense of ominous power rather than a plan pov shot. This is a little boring, imho, but it''s technically sound and fits the challenge.</td>', 'I think I would like this better if it had been taken with the camera held lower. Perhaps a low angle shot to give the doorway/building a sense of ominous power rather than a plan pov shot. This is a little boring, imho, but it''s technically sound and fits the challenge.', '2008-11-03 14:19:30.000000', NULL, 1),
(5041368, 735697, 70265, '<td valign="top">Ahhh ... this is definitely one of my top picks, and there are quite a few great entries in this contest. You''ve captured a dark spooky feel that is perfect with your abandoned building.is awesome.</td>', 'Ahhh ... this is definitely one of my top picks, and there are quite a few great entries in this contest. You''ve captured a dark spooky feel that is perfect with your abandoned building.is awesome.', '2008-11-03 14:20:28.000000', NULL, 1),
(5041371, 735718, 70265, '<td valign="top">Love the glow from the sunlight captured this time of day. Composition works the way you''ve cut the truck in half. nicely seen &amp; captured.</td>', 'Love the glow from the sunlight captured this time of day. Composition works the way you''ve cut the truck in half. nicely seen & captured.', '2008-11-03 14:21:23.000000', NULL, 1),
(5041372, 734489, 70265, '<td valign="top">like the B&amp;W processing.</td>', 'like the B&W processing.', '2008-11-03 14:21:46.000000', NULL, 1),
(5041373, 736021, 98141, '<td valign="top">I don''t know how I feel about these underwear shots in the woods - just a shot of dirty underwear doesn''t really tell a story. Yes, it''s clear that it was abandoned, but there are no clues as to why, and that makes me lose interest fast. Utilize your background in a pic like this, perhaps have a naked guy running away though the woods or about to jump in a lake? Just give us a little more of a story with it. Just staring at dirty underpants doesn''t make for an appealing pic. Where are his pants? Shirt? etc.</td>', 'I don''t know how I feel about these underwear shots in the woods - just a shot of dirty underwear doesn''t really tell a story. Yes, it''s clear that it was abandoned, but there are no clues as to why, and that makes me lose interest fast. Utilize your background in a pic like this, perhaps have a naked guy running away though the woods or about to jump in a lake? Just give us a little more of a story with it. Just staring at dirty underpants doesn''t make for an appealing pic. Where are his pants? Shirt? etc.', '2008-11-03 14:21:50.000000', NULL, 1),
(5041375, 735864, 70265, '<td valign="top">Blue duotone and dark edges add to the feel. Very unique &amp; perfect for the challenge.</td>', 'Blue duotone and dark edges add to the feel. Very unique & perfect for the challenge.', '2008-11-03 14:22:38.000000', NULL, 1),
(5041376, 735888, 98141, '<td valign="top">Ohhhh, so cute!! Cute factor = 10. Actually, I think I''m mesmerized by the cute factor and can''t come up with anything constructive to say! Nice dof.<br/> <br/>...<br/> <br/>So cute!!</td>', 'Ohhhh, so cute!! Cute factor = 10. Actually, I think I''m mesmerized by the cute factor and can''t come up with anything constructive to say! Nice dof. ... So cute!!', '2008-11-03 14:22:39.000000', NULL, 1),
(5041379, 735521, 98141, '<td valign="top">Hm, the yellow is a little strange. Feels a little like a cartoon. It''s not my cup of tea.</td>', 'Hm, the yellow is a little strange. Feels a little like a cartoon. It''s not my cup of tea.', '2008-11-03 14:23:25.000000', NULL, 1),
(5041380, 736086, 98141, '<td valign="top">Nice composition, I think you used the space of your frame very effectively in this.</td>', 'Nice composition, I think you used the space of your frame very effectively in this.', '2008-11-03 14:23:49.000000', NULL, 1),
(5041382, 736128, 70265, '<td valign="top">Great POV and the B&amp;W is perfect for this. Your depth of field is perfect as well, IMO. Nice, nice work.</td>', 'Great POV and the B&W is perfect for this. Your depth of field is perfect as well, IMO. Nice, nice work.', '2008-11-03 14:24:22.000000', NULL, 1),
(5041383, 736017, 98141, '<td valign="top">Okay, another dull, flat pic of the front of an old building. But the title tells a cool story. Your pic should be doing the majority of the story-telling, and it doesn''t. Fits the challenge though.</td>', 'Okay, another dull, flat pic of the front of an old building. But the title tells a cool story. Your pic should be doing the majority of the story-telling, and it doesn''t. Fits the challenge though.', '2008-11-03 14:25:04.000000', NULL, 1),
(5041384, 735156, 98141, '<td valign="top">Ooh, this is cool. I feel like I time-warped into the nuclear winter of the future.</td>', 'Ooh, this is cool. I feel like I time-warped into the nuclear winter of the future.', '2008-11-03 14:25:25.000000', NULL, 1),
(5041387, 735870, 98141, '<td valign="top">Hm, I could use a bike, and that one seems to have all its pieces... I think I would like this more if it weren''t a pov shot from your height. Try getting down a little for a different perspective of everyday objects.</td>', 'Hm, I could use a bike, and that one seems to have all its pieces... I think I would like this more if it weren''t a pov shot from your height. Try getting down a little for a different perspective of everyday objects.', '2008-11-03 14:26:12.000000', NULL, 1),
(5041388, 735748, 70265, '<td valign="top">This is hard to look at, but very well done. Your color processing is perfect for this, the range of tones is amazing. His expression captured speaks volumes.</td>', 'This is hard to look at, but very well done. Your color processing is perfect for this, the range of tones is amazing. His expression captured speaks volumes.', '2008-11-03 14:26:17.000000', NULL, 1),
(5041390, 735752, 70265, '<td valign="top">I see this at the top of the heap.</td>', 'I see this at the top of the heap.', '2008-11-03 14:26:42.000000', NULL, 1),
(5041391, 736083, 98141, '<td valign="top">Very fun to look at, and this one tells a story. Nice!</td>', 'Very fun to look at, and this one tells a story. Nice!', '2008-11-03 14:26:42.000000', NULL, 1),
(5041394, 735478, 70265, '<td valign="top">Great textures</td>', 'Great textures', '2008-11-03 14:26:58.000000', NULL, 1),
(5041395, 735567, 98141, '<td valign="top">I like this, you used your frame''s space well.</td>', 'I like this, you used your frame''s space well.', '2008-11-03 14:26:59.000000', NULL, 1),
(5041397, 735791, 70265, '<td valign="top">Anther one of my favs in this great challenge. I love the way her feet don''t reach the ground.</td>', 'Anther one of my favs in this great challenge. I love the way her feet don''t reach the ground.', '2008-11-03 14:27:39.000000', NULL, 1),
(5041398, 736114, 98141, '<td valign="top">This is a nice pic. It doesn''t pop for me, but I''m having trouble identifying why not. I think it might be a little dark for my tastes... but technically sound and fits the challenge.</td>', 'This is a nice pic. It doesn''t pop for me, but I''m having trouble identifying why not. I think it might be a little dark for my tastes... but technically sound and fits the challenge.', '2008-11-03 14:28:23.000000', NULL, 1),
(5041399, 736083, 70265, '<td valign="top">unique, cute!</td>', 'unique, cute!', '2008-11-03 14:28:43.000000', NULL, 1),
(5041401, 736019, 70265, '<td valign="top">One of my top picks. great DOF in this one.</td>', 'One of my top picks. great DOF in this one.', '2008-11-03 14:29:17.000000', NULL, 1),
(5041402, 735712, 98141, '<td valign="top">I get a very relaxed vibe from this pic. It''s not particularly interesting, but it is technically sound and fits the challenge. I like the colors.</td>', 'I get a very relaxed vibe from this pic. It''s not particularly interesting, but it is technically sound and fits the challenge. I like the colors.', '2008-11-03 14:29:25.000000', NULL, 1),
(5041403, 735939, 98141, '<td valign="top">Ooh, this screams, "haunted!" :) I like the lights from the city in the back and love, well, everything else about this pic. Well done!</td>', 'Ooh, this screams, "haunted!" :) I like the lights from the city in the back and love, well, everything else about this pic. Well done!', '2008-11-03 14:30:04.000000', NULL, 1),
(5041404, 736008, 98141, '<td valign="top">Not sure how I feel about the tilt. The rest of the pic is dull. I do like this better than similar pics without the tilt, at least that seperates it from the pack if nothing else.</td>', 'Not sure how I feel about the tilt. The rest of the pic is dull. I do like this better than similar pics without the tilt, at least that seperates it from the pack if nothing else.', '2008-11-03 14:31:08.000000', NULL, 1),
(5041405, 736027, 70265, '<td valign="top">Powerful. Perfect use of selective desat to emphasize your subject/title. A top pick. PS love the handprint too.</td>', 'Powerful. Perfect use of selective desat to emphasize your subject/title. A top pick. PS love the handprint too.', '2008-11-03 14:31:28.000000', NULL, 1),
(5041407, 735043, 98141, '<td valign="top">No, I don''t want snow! I know it''s coming here soon! The brightness makes it hard to see some details that I think would enhance the pic. I''d like to see a version with the exposure toned down a little.</td>', 'No, I don''t want snow! I know it''s coming here soon! The brightness makes it hard to see some details that I think would enhance the pic. I''d like to see a version with the exposure toned down a little.', '2008-11-03 14:32:05.000000', NULL, 1),
(5041409, 735156, 70265, '<td valign="top">what a find!</td>', 'what a find!', '2008-11-03 14:32:15.000000', NULL, 1),
(5041411, 735990, 98141, '<td valign="top">Nice reflection shot. Would like to see a version in color, post the original or an outtake, would  you? :)</td>', 'Nice reflection shot. Would like to see a version in color, post the original or an outtake, would  you? :)', '2008-11-03 14:32:39.000000', NULL, 1),
(5041413, 734790, 98141, '<td valign="top">Everything looks like it''s floating in steam, kind of eerie. I like it.</td>', 'Everything looks like it''s floating in steam, kind of eerie. I like it.', '2008-11-03 14:33:13.000000', NULL, 1),
