(5041761, 734503, 33535, '<td valign="top">looks right of that hänsel and gretel story. the colors are quite kitschy, but i guess if look at it in the context of the fairytale you quite nailed it...;)</td>', 'looks right of that hänsel and gretel story. the colors are quite kitschy, but i guess if look at it in the context of the fairytale you quite nailed it...;)', '2008-11-03 16:47:48.000000', NULL, 1),
(5041763, 734839, 63398, '<td valign="top">Beautiful in its abandonment. What a lovely view. 8</td>', 'Beautiful in its abandonment. What a lovely view. 8', '2008-11-03 16:48:09.000000', NULL, 1),
(5041765, 735408, 63398, '<td valign="top">Gritty &amp; evocative! Good job! 7</td>', 'Gritty & evocative! Good job! 7', '2008-11-03 16:48:28.000000', NULL, 1),
(5041769, 735658, 63398, '<td valign="top">I like the image for its composition &amp; processing.....7</td>', 'I like the image for its composition & processing.....7', '2008-11-03 16:49:25.000000', NULL, 1),
(5041772, 735678, 63398, '<td valign="top">Awesome! Gritty &amp; nasty......So bleak! 8</td>', 'Awesome! Gritty & nasty......So bleak! 8', '2008-11-03 16:49:55.000000', NULL, 1),
