(5047978, 735782, 63398, '<td valign="top">Good capture of a personal moment. 6</td>', 'Good capture of a personal moment. 6', '2008-11-05 22:53:19.000000', NULL, 1),
(5048031, 734884, 45475, '<td valign="top">Very mysterious. What''s the barbed wire for? Hmmm...<br/> <br/>Windows pack a punch with the sky reflected in them. Good work.</td>', 'Very mysterious. What''s the barbed wire for? Hmmm... Windows pack a punch with the sky reflected in them. Good work.', '2008-11-05 23:00:57.000000', NULL, 1),
