(5048044, 736012, 45475, '<td valign="top">The hooded figure is, imo, inconsequential. Crop the right third and you have an even greater image. Excellent tones and perspective.</td>', 'The hooded figure is, imo, inconsequential. Crop the right third and you have an even greater image. Excellent tones and perspective.', '2008-11-05 23:09:48.000000', NULL, 1),
(5048050, 735833, 45475, '<td valign="top">Love the burned edges, like an old photograph. Your editing rocks. Doesn''t seem abandoned to me though. Old - maybe; abandoned - nah.</td>', 'Love the burned edges, like an old photograph. Your editing rocks. Doesn''t seem abandoned to me though. Old - maybe; abandoned - nah.', '2008-11-05 23:13:05.000000', NULL, 1),
(5048053, 736080, 45475, '<td valign="top">Very pretty colours and composition, but kinda missing something...</td>', 'Very pretty colours and composition, but kinda missing something...', '2008-11-05 23:14:37.000000', NULL, 1),
(5048055, 734503, 45475, '<td valign="top">Oh my, looks like that has been picked up from somewhere else and just placed there in the middle of a forest. Weird.<br/> <br/>Cool editing, great colours.</td>', 'Oh my, looks like that has been picked up from somewhere else and just placed there in the middle of a forest. Weird. Cool editing, great colours.', '2008-11-05 23:16:06.000000', NULL, 1),
