(5048725, 736012, 95004, '<td valign="top">I love this photo with out the forsaken. I think its a strong enough photo with out the forsaken. I like the angle.</td>', 'I love this photo with out the forsaken. I think its a strong enough photo with out the forsaken. I like the angle.', '2008-11-06 12:14:34.000000', NULL, 1),
(5048730, 735156, 95004, '<td valign="top">wow. like colors. good angle. very rusty..engaging image.</td>', 'wow. like colors. good angle. very rusty..engaging image.', '2008-11-06 12:16:01.000000', NULL, 1),
