(5051133, 735639, 97225, '<td valign="top">Nice colourful shot. I like the reflection.</td>', 'Nice colourful shot. I like the reflection.', '2008-11-07 17:32:14.000000', NULL, 1),
(5051312, 734790, 70270, '<td valign="top">Carquinez Regional Shoreline?  Beautiful foreground -- love the silky texture on the water.  The sugar factory gets in the way of those nice bridge lines in the distance and the landscape hides the south tower of the new bridge.  A horizontal shot may have worked better here if you had a wide enough lens to capture both the pier and the full sweep of the bridges.</td>', 'Carquinez Regional Shoreline?  Beautiful foreground -- love the silky texture on the water.  The sugar factory gets in the way of those nice bridge lines in the distance and the landscape hides the south tower of the new bridge.  A horizontal shot may have worked better here if you had a wide enough lens to capture both the pier and the full sweep of the bridges.', '2008-11-07 18:47:33.000000', NULL, 1),
(5051368, 735853, 38248, '<td valign="top">I like this.  Interesting idea.</td>', 'I like this.  Interesting idea.', '2008-11-07 19:18:02.000000', NULL, 1),
(5051377, 735983, 38248, '<td valign="top">Nice. The only constructive critisicm I''d have is that the blurred weeds between the camera and the bike are just a bit distracting.  Just being picky :-)  I love the tones.</td>', 'Nice. The only constructive critisicm I''d have is that the blurred weeds between the camera and the bike are just a bit distracting.  Just being picky :-)  I love the tones.', '2008-11-07 19:21:25.000000', NULL, 1),
(5051380, 735759, 38248, '<td valign="top">Wow... what a perspective.  Amazing view.</td>', 'Wow... what a perspective.  Amazing view.', '2008-11-07 19:22:33.000000', NULL, 1),
(5051384, 736098, 38248, '<td valign="top">Nice.  I like it.  I like the depth of field and the sharpness of the vehicle.  The blurred weeds in the foreground are a tiny bit distracting, but overall I love the shot. 6</td>', 'Nice.  I like it.  I like the depth of field and the sharpness of the vehicle.  The blurred weeds in the foreground are a tiny bit distracting, but overall I love the shot. 6', '2008-11-07 19:24:49.000000', NULL, 1),
(5051387, 735939, 38248, '<td valign="top">Very cool.  Looks like something the Adams Family would live in.  Nice work.</td>', 'Very cool.  Looks like something the Adams Family would live in.  Nice work.', '2008-11-07 19:25:29.000000', NULL, 1),
(5051389, 735575, 38248, '<td valign="top">Nice mood to this shot.  The expression on her face works perfectly.</td>', 'Nice mood to this shot.  The expression on her face works perfectly.', '2008-11-07 19:26:05.000000', NULL, 1),
(5051395, 736126, 38248, '<td valign="top">Nice.  I like the symmetrical crop.  All the textures make for an interesting photo.</td>', 'Nice.  I like the symmetrical crop.  All the textures make for an interesting photo.', '2008-11-07 19:28:17.000000', NULL, 1),
(5051397, 735078, 38248, '<td valign="top">Beautiful.  Love the dark tones and colors.  Very sharp details on the nest.  Nicely done.</td>', 'Beautiful.  Love the dark tones and colors.  Very sharp details on the nest.  Nicely done.', '2008-11-07 19:29:20.000000', NULL, 1),
