(5051403, 735567, 38248, '<td valign="top">Very cool.  I''m not sure I like the black borders on top and bottom, but that''s just personal preference.  Nicely seen.  The shadow of the tree on the wall adds a nice touch.</td>', 'Very cool.  I''m not sure I like the black borders on top and bottom, but that''s just personal preference.  Nicely seen.  The shadow of the tree on the wall adds a nice touch.', '2008-11-07 19:33:56.000000', NULL, 1),
(5051406, 734489, 38248, '<td valign="top">Awesome shot.  I don''t like the black on top and bottom, but that''s just personal preference.  Love the angle and the sky.</td>', 'Awesome shot.  I don''t like the black on top and bottom, but that''s just personal preference.  Love the angle and the sky.', '2008-11-07 19:34:50.000000', NULL, 1),
(5051409, 735366, 38248, '<td valign="top">I like the perspective and the cracked window.</td>', 'I like the perspective and the cracked window.', '2008-11-07 19:35:55.000000', NULL, 1),
