(5052316, 735947, 99518, '<td valign="top">Very nice photo. The stars and aurora make a good backdrop.</td>', 'Very nice photo. The stars and aurora make a good backdrop.', '2008-11-08 10:20:41.000000', NULL, 1),
(5052955, 735809, 91496, '<td valign="top">Cool shot.  I like how the parts work together.  Maybe a polarizor to remove the water reflections.  It looks a little oversharpened.</td>', 'Cool shot.  I like how the parts work together.  Maybe a polarizor to remove the water reflections.  It looks a little oversharpened.', '2008-11-08 20:12:16.000000', NULL, 1),
