(5052960, 735718, 91496, '<td valign="top">I like the shadows on the car.  The reds might be a bit bright in contrast to the muted car.</td>', 'I like the shadows on the car.  The reds might be a bit bright in contrast to the muted car.', '2008-11-08 20:15:22.000000', NULL, 1),
(5052961, 734924, 91496, '<td valign="top">Cool.  The dark and light play well together here.  Does not scream "abandoned" to me.</td>', 'Cool.  The dark and light play well together here.  Does not scream "abandoned" to me.', '2008-11-08 20:16:54.000000', NULL, 1),
(5052963, 734884, 91496, '<td valign="top">Gritty.  I like the opposing diagonals and the crazy lines of the barbed wire. The lighting is a little harsh.</td>', 'Gritty.  I like the opposing diagonals and the crazy lines of the barbed wire. The lighting is a little harsh.', '2008-11-08 20:18:42.000000', NULL, 1),
(5052967, 734854, 91496, '<td valign="top">Cool B&amp;W.  I like the muted tone.  Does not evoke a stong sense of "abandoned".</td>', 'Cool B&W.  I like the muted tone.  Does not evoke a stong sense of "abandoned".', '2008-11-08 20:20:33.000000', NULL, 1),
(5052968, 735864, 91496, '<td valign="top">Funky color scheme.</td>', 'Funky color scheme.', '2008-11-08 20:21:25.000000', NULL, 1),
(5052969, 735940, 91496, '<td valign="top">Gave me a chuckle.  Nice DOF.  The crop might be a little too narrow.</td>', 'Gave me a chuckle.  Nice DOF.  The crop might be a little too narrow.', '2008-11-08 20:22:18.000000', NULL, 1),
(5052970, 735078, 91496, '<td valign="top">Just wonderful.  I like the lines which lead to the nest.  The color is great.  Maybe a touch mroe DOF to keep the lead petal in focus, but that is a nit.</td>', 'Just wonderful.  I like the lines which lead to the nest.  The color is great.  Maybe a touch mroe DOF to keep the lead petal in focus, but that is a nit.', '2008-11-08 20:23:44.000000', NULL, 1),
(5052971, 735662, 91496, '<td valign="top">Does not evoke a stong sense of "abandoned".</td>', 'Does not evoke a stong sense of "abandoned".', '2008-11-08 20:24:21.000000', NULL, 1),
(5052973, 734853, 91496, '<td valign="top">Cool textures and muted colors.  Crop is a little tight, cutting off the letters.</td>', 'Cool textures and muted colors.  Crop is a little tight, cutting off the letters.', '2008-11-08 20:25:51.000000', NULL, 1),
(5052977, 735699, 91496, '<td valign="top">I like the compsition.  I am less sure about the tone of the B&amp;W, as it looks a bit faded.  That may have been your intent.</td>', 'I like the compsition.  I am less sure about the tone of the B&W, as it looks a bit faded.  That may have been your intent.', '2008-11-08 20:28:41.000000', NULL, 1),
(5052979, 735698, 91496, '<td valign="top">Do not get it.  I like the wispy effect on the girl.  The relfection on the clock detracts from the photo.</td>', 'Do not get it.  I like the wispy effect on the girl.  The relfection on the clock detracts from the photo.', '2008-11-08 20:30:07.000000', NULL, 1),
(5052981, 735853, 91496, '<td valign="top">Great idea.  I like the composition, with the curl of the negative.  The diagonal relection thing detracts from the effect and goes right through you only subject.</td>', 'Great idea.  I like the composition, with the curl of the negative.  The diagonal relection thing detracts from the effect and goes right through you only subject.', '2008-11-08 20:32:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5053044, 735182, 76335, '<td valign="top">Gritty -- nice geometry, theme.</td>', 'Gritty -- nice geometry, theme.', '2008-11-08 21:43:38.000000', NULL, 1),
(5053047, 736083, 76335, '<td valign="top">Interesting processing -- maybe a bit much. High pass? Good theme, story.</td>', 'Interesting processing -- maybe a bit much. High pass? Good theme, story.', '2008-11-08 21:45:35.000000', NULL, 1),
(5053049, 735271, 76335, '<td valign="top">Vignette strikes me as a bit strong, but well composed.</td>', 'Vignette strikes me as a bit strong, but well composed.', '2008-11-08 21:45:59.000000', NULL, 1),
(5053050, 735567, 76335, '<td valign="top">Seems slightly OOF, white balance looks off. Cool looking house though and well composed.</td>', 'Seems slightly OOF, white balance looks off. Cool looking house though and well composed.', '2008-11-08 21:46:35.000000', NULL, 1),
(5053053, 736019, 76335, '<td valign="top">Great idea and well composed. BW was a good choice. Was the bokeh effect done in PP? Foreground blur strikes me as a bit strong. But what do I know...</td>', 'Great idea and well composed. BW was a good choice. Was the bokeh effect done in PP? Foreground blur strikes me as a bit strong. But what do I know...', '2008-11-08 21:48:21.000000', NULL, 1),
(5053055, 736020, 76335, '<td valign="top">Too much sky, I think. Some foreground is needed to give the house context and anchor the shot.</td>', 'Too much sky, I think. Some foreground is needed to give the house context and anchor the shot.', '2008-11-08 21:48:58.000000', NULL, 1),
(5053056, 735967, 91496, '<td valign="top">Nice B&amp;W.  DOF works well.  I like how the tree frames the left side.</td>', 'Nice B&W.  DOF works well.  I like how the tree frames the left side.', '2008-11-08 21:49:20.000000', NULL, 1),
(5053057, 735757, 76335, '<td valign="top">Interesting idea, but there''s too much to see. The poster seems to grab the viewer''s attention first, but the real subject of the challenge (I''m guessing) is the garbage. Needs some compositional adjustment.</td>', 'Interesting idea, but there''s too much to see. The poster seems to grab the viewer''s attention first, but the real subject of the challenge (I''m guessing) is the garbage. Needs some compositional adjustment.', '2008-11-08 21:50:06.000000', NULL, 1),
(5053058, 735983, 76335, '<td valign="top">Not sure the red in the highlights add anything. Nicely lit and composed.</td>', 'Not sure the red in the highlights add anything. Nicely lit and composed.', '2008-11-08 21:50:45.000000', NULL, 1),
(5053059, 735728, 76335, '<td valign="top">Not seeing the abandonment and nothing seems to be in focus.</td>', 'Not seeing the abandonment and nothing seems to be in focus.', '2008-11-08 21:51:10.000000', NULL, 1),
(5053060, 735156, 76335, '<td valign="top">Looks more like case of arson than abandonment. Strong image.</td>', 'Looks more like case of arson than abandonment. Strong image.', '2008-11-08 21:52:05.000000', NULL, 1),
(5053063, 736021, 76335, '<td valign="top">Lovely.</td>', 'Lovely.', '2008-11-08 21:52:54.000000', NULL, 1),
(5053064, 735703, 91496, '<td valign="top">Nice idea.  The title ties in with the unnatural lighting effect (HDR I assume).  The textures are cool, but overall the picture lacks an interesting subject.</td>', 'Nice idea.  The title ties in with the unnatural lighting effect (HDR I assume).  The textures are cool, but overall the picture lacks an interesting subject.', '2008-11-08 21:53:29.000000', NULL, 1),
(5053066, 735993, 76335, '<td valign="top">Too much color. Also, it needs some further contextual clues. I''m not sure what I''m looking at. A street scene? Maybe a different angle would have helped.</td>', 'Too much color. Also, it needs some further contextual clues. I''m not sure what I''m looking at. A street scene? Maybe a different angle would have helped.', '2008-11-08 21:54:13.000000', NULL, 1),
