(5054149, 735728, 50695, '<td valign="top">aww, Mommy looks tolerant to me. Great picture.</td>', 'aww, Mommy looks tolerant to me. Great picture.', '2008-11-09 22:08:10.000000', NULL, 1),
(5054151, 736131, 34938, '<td valign="top">beautiful tones and light</td>', 'beautiful tones and light', '2008-11-09 22:08:44.000000', NULL, 1),
(5054153, 736027, 50695, '<td valign="top">I''m not crazy about selective desat, but I''m trying to be open-minded. She is so small in the picture that it does seem subtle, more subtle than one would think a rose in the desert would be. The composition is great otherwise. I''m going to look the other way this time! ;)</td>', 'I''m not crazy about selective desat, but I''m trying to be open-minded. She is so small in the picture that it does seem subtle, more subtle than one would think a rose in the desert would be. The composition is great otherwise. I''m going to look the other way this time! ;)', '2008-11-09 22:09:53.000000', NULL, 1),
(5054155, 735985, 50695, '<td valign="top">Great composition and oh how I love the kitties.</td>', 'Great composition and oh how I love the kitties.', '2008-11-09 22:10:55.000000', NULL, 1),
(5054157, 735864, 50695, '<td valign="top">way creepy. good juxtaposition of foreground, middle ground and background. This shows a real sophistication in creating a picture.</td>', 'way creepy. good juxtaposition of foreground, middle ground and background. This shows a real sophistication in creating a picture.', '2008-11-09 22:11:53.000000', NULL, 1),
